contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        uint beforeBalance = address(c).balance;
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint afterDepositBalance = address(c).balance;

        uint beforeCallerBalance = address(this).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;

        assert(
            reverted ||
            (afterBalance == afterDepositBalance - depositAmount &&
             afterCallerBalance == beforeCallerBalance + depositAmount &&
             afterBalance >= 0)
        );
    }
}

