// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeBalance = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint afterBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;
        assertTrue(reverted ||
            (afterBalance == afterDepositBalance - depositAmount &&
             afterCallerBalance == beforeCallerBalance + depositAmount &&
             afterBalance >= 0));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
